        if (lutaViu && cb2 === AUTO.field) { luta = false; lutaViu = false; lutaCabo = false; lutaCalma = 0; foto = null; entregaAdiados(); return; }
        // desistiu da espera sem lutar: 2 s seguidos livres no mapa
